import SwiftUI
struct SettingsView: View { @EnvironmentObject var settings: AppSettings; var body: some View { TabView { Form { Picker("Appearance",selection:$settings.appearance) { ForEach(AppAppearance.allCases){ Text($0.title).tag($0.rawValue) } }; Picker("Accent",selection:$settings.accentColor) { Text("Indigo").tag("indigo"); Text("Blue").tag("blue"); Text("Purple").tag("purple"); Text("Orange").tag("orange"); Text("Green").tag("green") } }.padding().tabItem { Label("General",systemImage:"gear") }; Form { Toggle("Autosave changes",isOn:$settings.autosave); Toggle("Show word count",isOn:$settings.showWordCount); Stepper("Editor size: \(Int(settings.editorFontSize)) pt",value:$settings.editorFontSize,in:12...28,step:1) }.padding().tabItem { Label("Editor",systemImage:"text.cursor") } }.frame(width:460,height:260) } }
